from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi_cache.decorator import cache

router = APIRouter(prefix="/organization")

def tenant_roster_key_builder(func, namespace: str = "", request: Request = None, *args, **kwargs):
    user = kwargs.get("user")
    org_id = user.organization_id if user else "guest"
    return f"{namespace}:{request.url.path}:org_{org_id}"

@router.get("/team-roster")
@cache(expire=600, key_builder=tenant_roster_key_builder)
async def get_organization_team_roster(
    roster_service: RosterService = Depends(get_roster_service),
    user: AuthUser = Depends(get_authenticated_user)
):
    members = await roster_service.get_org_members(user.organization_id)
    return {
        "organization_id": user.organization_id,
        "members": [{"id": m.id, "email": m.email, "role": m.role, "phone": m.phone} for m in members]
    }
